import 'package:flutter/material.dart';
class BreedLibraryScreen extends StatefulWidget{const BreedLibraryScreen({super.key});@override State<BreedLibraryScreen> createState()=>_BreedLibraryScreenState();}
class _BreedLibraryScreenState extends State<BreedLibraryScreen>{String species='Dog',query='';static const dogs=['Labrador Retriever','Golden Retriever','German Shepherd','Poodle','French Bulldog','Beagle','Dachshund','Mixed breed'];static const cats=['Domestic Shorthair','Domestic Longhair','Maine Coon','Siamese','Ragdoll','Persian','Bengal','Mixed breed'];@override Widget build(BuildContext context){final items=(species=='Dog'?dogs:cats).where((e)=>e.toLowerCase().contains(query.toLowerCase())).toList();return Scaffold(appBar:AppBar(title:const Text('Breed library')),body:ListView(padding:const EdgeInsets.all(16),children:[SegmentedButton<String>(segments:const[ButtonSegment(value:'Dog',label:Text('Dogs')),ButtonSegment(value:'Cat',label:Text('Cats'))],selected:{species},onSelectionChanged:(v)=>setState(()=>species=v.first)),const SizedBox(height:12),TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search breeds')),const SizedBox(height:12),...items.map((b)=>Card(child:ListTile(title:Text(b),subtitle:const Text('Breed overview · care considerations'),trailing:const Icon(Icons.chevron_right),onTap:()=>showModalBottomSheet(context:context,builder:(c)=>Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(b,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),const Text('Individual animals vary. Breed descriptions are general tendencies, not guarantees of temperament, health, hypoallergenic status or suitability. Learn about the individual pet before making adoption decisions.'),TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]))))))]));}}
